<?php
 namespace Pterodactyl\Services\Dezerx\Minecraft; use Throwable; use Pterodactyl\Models\Server; use Illuminate\Support\Facades\Http; use Illuminate\Support\Facades\Log; use Pterodactyl\Repositories\Wings\DaemonFileRepository; use Pterodactyl\Repositories\Wings\DaemonPowerRepository; use Pterodactyl\Repositories\Wings\DaemonServerRepository; use Pterodactyl\Repositories\Wings\DaemonCommandRepository; class ServerFiles { public const MAX_PLAYER_FILE = 2_000_000; private ?DaemonFileRepository $filesRepository = null; public function __construct(public readonly Server $server) { } public function listFiles(string $path): ?array { try { $entries = $this->files()->getDirectory($path); } catch (Throwable) { return null; } return array_map(fn (array $entry) => [ 'name' => (string) ($entry['name'] ?? ''), 'size' => (int) ($entry['size'] ?? 0), 'directory' => (bool) ($entry['directory'] ?? false), 'modified_at' => $entry['modified'] ?? null, ], $entries); } public function listFilesMany(array $paths): array { $out = []; foreach (array_unique($paths) as $path) { $out[$path] = $this->listFiles($path); } return $out; } public function fileContents(string $path, ?int $maxBytes = null): ?string { try { return $this->files()->getContent($path, $maxBytes); } catch (Throwable) { return null; } } public function writeFile(string $path, string $contents): bool { try { $this->files()->putContent($path, $contents); } catch (Throwable) { return false; } return true; } public function writeStream(string $path, mixed $stream): bool { try { $this->files()->putStream($path, $stream); } catch (Throwable) { return false; } return true; } public function deletePaths(string $root, array $names): bool { if ($names === []) { return true; } try { $this->files()->deleteFiles($root, array_values($names)); } catch (Throwable) { return false; } return true; } public function createDirectory(string $path): bool { $path = '/' . trim(str_replace('\\', '/', $path), '/'); if ($path === '/' || str_contains($path, '..')) { return false; } $name = basename($path); $parent = dirname($path); try { $this->files()->createDirectory($name, $parent); } catch (Throwable) { return false; } return true; } public function renamePath(string $root, string $from, string $to): bool { try { $this->files()->renameFiles($root, [['from' => $from, 'to' => $to]]); } catch (Throwable) { return false; } return true; } public function chmod(string $root, string $file, string $mode = '0755'): bool { try { $this->files()->chmodFiles($root, [['file' => $file, 'mode' => $mode]]); } catch (Throwable) { return false; } return true; } public function pullFile(string $directory, string $url, string $filename): bool { foreach (array_values(array_unique([$this->finalUrl($url), $url])) as $candidate) { try { $this->files()->pull($candidate, $directory, ['filename' => $filename, 'use_header' => false]); return true; } catch (Throwable $exception) { Log::warning('Node refused a file pull', [ 'server' => $this->server->uuid, 'directory' => $directory, 'filename' => $filename, 'resolved' => $candidate !== $url, 'error' => $exception->getMessage(), ]); } } return false; } public function decompress(string $root, string $file): bool { try { $this->files()->decompressFile($root, $file); } catch (Throwable) { return false; } return true; } public function entrySize(string $root, string $name): ?int { foreach ($this->listFiles($root) ?? [] as $entry) { if (($entry['name'] ?? '') === $name) { return (int) ($entry['size'] ?? 0); } } return null; } public function allocations(): array { return $this->server->allocations ->map(fn ($allocation) => ['ip' => (string) $allocation->ip, 'port' => (int) $allocation->port]) ->all(); } public function powerState(): string { try { return (string) (app(DaemonServerRepository::class) ->setServer($this->server) ->getDetails()['state'] ?? 'offline'); } catch (Throwable) { return 'offline'; } } public function powerStateOrNull(): ?string { try { return (string) (app(DaemonServerRepository::class)->setServer($this->server)->getDetails()['state'] ?? 'offline'); } catch (Throwable) { return null; } } public function setPower(string $signal): bool { try { app(DaemonPowerRepository::class)->setServer($this->server)->send($signal); } catch (Throwable) { return false; } return true; } private function finalUrl(string $url): string { try { $response = Http::withOptions([ 'allow_redirects' => ['max' => 5, 'track_redirects' => true], ])->timeout(15)->head($url); $history = $response->header('X-Guzzle-Redirect-History'); if ($history === '') { return $url; } $hops = array_filter(array_map('trim', explode(',', $history))); return end($hops) ?: $url; } catch (Throwable) { return $url; } } public function sendCommand(string $command): bool { try { app(DaemonCommandRepository::class)->setServer($this->server)->send($command); } catch (Throwable) { return false; } return true; } private function files(): DaemonFileRepository { if ($this->filesRepository === null) { $this->filesRepository = app(DaemonFileRepository::class)->setServer($this->server); } return $this->filesRepository; } } 